					"修复交换机网口保存失败：非 Wi‑Fi 接口不再携带空的无线频段字段，电口和光口可按真实启用、接线、角色和速率状态保存。",
					"交换机资产详情新增“网口状态”参数卡：按电口在前、光口在后且组内名称自然排序，逐口显示接口类型、启用状态、接线状态、上联 / 下联 / 通用角色、支持或协商速率和关系中的已连接设备；已接线但关系未建档时显示“对端未关联”，未接线端口不把历史关系冒充当前连接。具体端口数量和状态只读取真实 asset_interfaces 与 asset_relations，不从产品模板伪造。",
					"修复资产编辑里的接口弹窗关闭联动：取消、关闭或保存接口时只关闭当前接口弹窗，外层资产编辑工作台继续保持打开，避免重复进入编辑页。",
					"设备档案网络区域统一显示已填写的“管理页面”：路由器、光猫、交换机等资产只要明确保存管理 URL，就会在左侧档案中提供可点击入口；未填写时不占用位置，也不会根据普通 IPv4 擅自推断网页后台。",
					"优化资产详情展示页：桌面端改为紧凑的单页自然滚动，第一列只保留吸顶的固定图片框和双列设备 / 线路档案，参数目录统一放到右侧参数标题下方；无封面时保留“暂无图片”中性空框，不使用图库或历史图片补位。右侧参数卡压缩无效间距、固定每排两张并随页面自然展开，所有参数卡按最高卡片统一高度，信息较少的卡片允许底部留白；长参数组不再强制独占整行，也不再使用内部滚动或父级裁切。手机和平板保持单列布局与紧凑横向目录，数据、编辑入口和严格类型模板保持不变。",
					"新增光猫 / ONT 严格类型模板：通过固定工作角色区分桥接光猫、光猫路由一体机和 iFTTR 主网关，统一身份归属、光纤接入、路由管理、无线、有线、其他端口电源与设备标识字段；列表、详情、编辑、完整度、导入导出和资料补全使用同一规格，历史未知字段只读兼容。",
					"资产接口新增 optical 光纤类型，并把接口能力、启用状态、物理接线状态和资产关系分开维护；PON 作为上联、下联光口作为下联，USB、电话、电源和按钮只保留为硬件参数。",
					"Hub 新增 ONT 写入和关系边界：拒绝模板外字段、秘密字段、无效固定选项和错误身份格式；宽带只能连接 PON / WAN 上联，Wi-Fi 关系不能连接未启用的 Wi-Fi 接口；ONT 详情会直接显示宽带到 PON 与终端到无线频段的真实关系，待建档交换机只保留中性说明。",
					"ONT 的 LAN 网段改为 IPv4 CIDR 输入，表单直接示例 192.168.1.0/24，Hub 同步拒绝无效网段；资产位置控件移除“一级 / 二级”层级标识，只保留位置与房间 / 子位置选择；所有资产编辑页统一提供可保存的备注输入框。",
					"互联网接入资产升级为首个严格类型模板：宽带按线路资源维护名称、三大运营商、资源状态、线路技术、认证方式、上下行带宽、动态公网地址、套餐续费、接入关系和备注；位置、用途、颜色、硬件、接口与网卡速率不再混入宽带档案或完整度，列表与详情统一显示线路档案，详情卡片不再重复显示基础资料或通用硬件说明。",
					"宽带接入关系固定为互联网接入指向光猫、路由器或网关的 PON / WAN 接口：新增 PON 接口种类，Hub 会拒绝反向、错误目标、无接口和第二条当前外网关系；未关联时显示待关联接入设备。",
					"宽带公网 IPv4 / IPv6 简化为 DDNS 自动维护：默认开启推荐的 30 分钟间隔，也可固定选择 15 分钟、1 小时、6 小时、12 小时或 24 小时；详情与编辑页统一显示当前地址、上次与下次更新时间、自动更新开关和手动刷新。检测成功直接更新正式地址，不再需要人工确认或候选地址；双协议独立失败时保留各自上次成功值，关闭自动更新后仍可手动刷新。",
					"互联网接入保存和资料补全新增严格白名单：运营商别名自动归一，固定选项与正数带宽由前端和 Hub 双重校验，历史 metadata 保留只读兼容，Agent 只能提出模板允许字段的候选。",
					"资产详情标题栏直接显示接口、关系、维护和附件，后接编辑和固定在最右侧的更多；常用档案操作无需再展开菜单，更多中仅保留删除资产。窄屏下标题信息和操作组会自然换行并保持靠右，不再出现按钮越界或横向滚动。",
					"资产中心清单将接入网络拆分为网络接入方式和网卡速率：展示全部网卡，有线与 Wi-Fi 同时接入时组合显示，当前接入使用绿色标识，主接口使用实心星标；宽带与网页服务的网卡速率明确显示无。资产详情和编辑工作台可统一新增、编辑、删除网卡并维护接入状态与网络参数。",
					"资产中心新增本地媒体库：资产编辑内可上传原图、裁剪并另存真实版本、设置封面及管理图片库；媒体文件保存在可配置的本地对象存储目录。资产详情只展示用户明确设置为封面的图片，图片库和历史图片不再补位；未设置封面时不显示图片区。已入库图片统一使用“设备名称-图片编号”（如“宽带-01”）命名，不附带资产编号。",
					"图片库编辑升级为固定 16:9 白底画布：原图默认按比例完整显示，支持滑块与鼠标滚轮在 0.25× 至 4× 之间缩放，并可拖动到画布外；未被图片覆盖的区域保留为白色，保存后生成独立的 1600×900 JPEG。",
					"设备图片候选目标从 10 张提高到 15 张，互联网接入与网页服务的服务商 Logo 仍保持最多 4 张；PocketBase 候选文件字段上限同步迁移到 15，避免第 11 张开始归档失败。点击候选图会先在上方 16:9 白底框中完整预览，不直接修改封面，每张候选卡只保留一个加入图片库按钮。",
					"根治图片编辑保存结果与预览不一致的问题：前端提交图片在固定画布中的真实位置和尺寸，Hub 按同一组参数在纯白 1600×900 画布上合成、自动裁掉越界部分并输出 JPEG；每次保存保留来源原图并生成带新编号的独立图片。历史 crop 配方继续使用旧渲染路径，可正常读取和重建。",
					"修复候选图重复入库无反应：相同图片始终返回统一的媒体与版本结构；曾删除的图片会在原版本和对象文件完整时恢复、重新分配可用图片编号，并保持封面与图库关系为空。",
					"修复候选入库后的选中状态持续抢占：新入库媒体只自动选中一次，之后手动切换或保存新编辑图会正常接管大预览；选中图片的大预览与编辑器共享同一次本地对象读取，并明确显示图片加载中，避免重复请求偶发失败后编辑器长期禁用。",
					"修复图片库编号在刷新后互换的问题：图片名称分配后保持稳定，列表加载不再按随机记录 ID 重新编号；新增或编辑保存的图片使用首个可用编号，已删除图片留下的空位可安全复用。",
