					"网站监控统计新增待检测状态，手机端网站顶部在未检测完成时显示待检测数量，不再因为没有异常就显示正常。",
					"首页网站监控摘要新增待检测和暂无监控状态，不再用地址检测正常覆盖未知状态。",
